import { app } from 'electron';
import { join } from 'node:path';

/** App icon (multi-resolution ICO generated by tools/make-icon.ts): tray, welcome window; the packaged exe/installer get it via electron-builder. */
export const iconPath = (): string =>
  app.isPackaged ? join(process.resourcesPath, 'icon.ico') : join(app.getAppPath(), 'build', 'icon.ico');
